for c in cal_data:
    dt = c['date']
    y = int(dt.split('-')[0])
    m = int(dt.split('-')[1])
    raw_type = c.get('status_desc', '')
    if '法定' in raw_type or '节日' in raw_type or c.get('is_legal_holiday'):
        day_type = '法定节假日'
    elif '调休' in raw_type or c.get('is_shift_off'):
        day_type = '调休日'
    elif '调班' in raw_type or c.get('is_shift_work'):
        day_type = '调班日'
    elif '周末' in raw_type or c.get('is_weekend'):
        day_type = '周末日'
    else:
        day_type = '工作日'

    if not frappe.db.exists('Ashan Holiday Calendar', dt):
        doc = frappe.new_doc('Ashan Holiday Calendar')
        doc.calendar_date = dt
        doc.year = y
        doc.month = m
        doc.day_type = day_type
        doc.is_workday = c['is_workday']
        doc.is_legal_holiday = c['is_legal_holiday']
        doc.is_shift_off = c['is_shift_off']
        doc.is_shift_work = c['is_shift_work']
        doc.holiday_name = c['remark']
        doc.insert(ignore_permissions=True)
